# Title: Verify pickle-daily App hides AI-powered Templates in Discovery view
# Feature: Content Generation / pickle PRD testcases high
import pytest

pytestmark = pytest.mark.asyncio


async def test_verify_pickle_daily_app_hides_ai_powered_templates_in_discov(page, base_url):
    # Navigate to the Discovery feed
    await page.goto(base_url.rstrip('/') + '/discovery')
    
    try:
        await page.wait_for_load_state('networkidle', timeout=8000)
    except Exception:
        pass

    # Verify Discovery feed is visible
    discovery_heading = page.get_by_role('heading', name='Discovery')
    await discovery_heading.wait_for(state='visible', timeout=8000)
    assert await discovery_heading.is_visible(), 'Discovery feed should be visible'

    # Inspect available content categories and template list
    # We need to ensure that AI-powered or video-based templates are absent.
    # Assuming templates are rendered as cards or list items.
    # We look for indicators of AI/Video (e.g., badges, labels, or specific icons).
    
    # Check for presence of any template cards
    template_cards = page.locator('[data-testid="template-card"]')
    
    # If there are templates, verify none of them have "AI" or "Video" badges
    # This assumes a standard UI pattern where templates might have badges like "AI" or "Video"
    ai_badges = page.get_by_text('AI', exact=True)
    video_badges = page.get_by_text('Video', exact=True)
    
    # Assert that AI or Video badges are not visible in the discovery feed
    ai_visible = await ai_badges.first.is_visible()
    video_visible = await video_badges.first.is_visible()
    
    assert not ai_visible, 'AI-powered templates should not be visible in pickle-daily Discovery feed'
    assert not video_visible, 'Video-based templates should not be visible in pickle-daily Discovery feed'
